def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote: represents one quote character
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field: runs to next comma
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain a double quote
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < n:
                i += 1  # Skip the comma

    return fields

